import Foundation

func extractJSONObject(from text: String) -> Data? {
    guard let start = text.firstIndex(of: "{"),
          let end = text.lastIndex(of: "}"), start < end else { return nil }
    return String(text[start...end]).data(using: .utf8)
}
struct Item: Codable { let term: String; let reading: String; let meaning: String }
struct Resp: Codable { let items: [Item] }

var pass = 0, fail = 0
func check(_ n: String, _ got: Any, _ want: Any) {
    if "\(got)" == "\(want)" { pass += 1; print("✅ \(n)") } else { fail += 1; print("❌ \(n): got \(got) want \(want)") }
}
func decode(_ s: String) -> Int {
    guard let d = extractJSONObject(from: s), let r = try? JSONDecoder().decode(Resp.self, from: d) else { return -1 }
    return r.items.count
}

